import{_ as d,o as e,c as a,ak as o}from"./chunks/framework.DxrHb2fb.js";const y=JSON.parse('{"title":"停留时长","description":"","frontmatter":{},"headers":[],"relativePath":"design/dwell.md","filePath":"design/dwell.md","lastUpdated":1790453899000}'),r={name:"design/dwell.md"};function l(i,t,h,n,c,s){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="停留时长" tabindex="-1">停留时长 <a class="header-anchor" href="#停留时长" aria-label="Permalink to &quot;停留时长&quot;">​</a></h1><p>提示延迟、自动播放间隔、轻提示停留、滚动条隐藏延迟这类时间是等待，不是动效：它们决定一件事什么时候发生，不决定变化本身怎么过渡。停留时长作为组件属性给出缺省值，不经动效令牌，也不受减弱动效影响——减弱动效去掉的是运动，不是让提示更早消失或更晚出现。</p><p>唯一的例外是自动播放：持续变化的内容在减弱动效下不自己起播。Carousel 在减弱动效下不自动轮播，用户按播放开关照常播放。</p><h2 id="悬停与长按" tabindex="-1">悬停与长按 <a class="header-anchor" href="#悬停与长按" aria-label="Permalink to &quot;悬停与长按&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>属性</th><th style="text-align:right;">缺省</th><th>说明</th></tr></thead><tbody><tr><td>Tooltip</td><td><code>openDelay</code> / <code>closeDelay</code></td><td style="text-align:right;">700 / 300ms</td><td>悬停与聚焦打开前的等待、离开后的保留</td></tr><tr><td>HoverCard</td><td><code>openDelay</code> / <code>closeDelay</code></td><td style="text-align:right;">700 / 300ms</td><td>同 Tooltip</td></tr><tr><td>Menu 子菜单</td><td><code>hoverOpenDelay</code> / <code>hoverCloseDelay</code></td><td style="text-align:right;">100 / 300ms</td><td>悬停展开子菜单前的等待；指针在安全三角里停滞超过关闭延迟即放弃</td></tr><tr><td>SideNav 折叠态弹出</td><td>无</td><td style="text-align:right;">100 / 300ms</td><td>图标栏上悬停顶层分支、弹出子级面板前的等待与离开后的保留；与 Menu 子菜单的缺省同源，内部取值，不作为属性开放</td></tr><tr><td>NavigationMenu</td><td><code>delayDuration</code> / <code>skipDelayDuration</code></td><td style="text-align:right;">200 / 300ms</td><td>悬停展开前的等待；收起后这段时间内碰到另一个入口直接展开</td></tr><tr><td>Pagination 省略位浮层</td><td><code>openDelay</code> / <code>closeDelay</code></td><td style="text-align:right;">200 / 300ms</td><td>悬停省略位打开页码浮层</td></tr><tr><td>ContextMenu</td><td><code>longPressDelay</code></td><td style="text-align:right;">700ms</td><td>触屏长按打开菜单</td></tr></tbody></table><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>属性</th><th style="text-align:right;">缺省</th><th>说明</th></tr></thead><tbody><tr><td>Toast</td><td><code>duration</code></td><td style="text-align:right;">4000ms</td><td>停多久自动收起；<code>loading</code> 或不大于 0 时不自动收起；悬停、聚焦、<code>paused</code> 与页面闲置时按住计时，恢复后从剩余时间接着走</td></tr><tr><td>Notification</td><td><code>duration</code></td><td style="text-align:right;">5000ms</td><td>同 Toast；单条没写取组件属性，都没写取缺省</td></tr><tr><td>Clipboard</td><td><code>timeout</code></td><td style="text-align:right;">3000ms</td><td>复制成功态保留多久回到初始态；不大于 0 时不回落</td></tr></tbody></table><p>轻提示与通知卡片上的倒计时条在减弱动效下按秒分段显示，这改变的是画法，停留时长不变。</p><h2 id="自动播放、自动前进与周期" tabindex="-1">自动播放、自动前进与周期 <a class="header-anchor" href="#自动播放、自动前进与周期" aria-label="Permalink to &quot;自动播放、自动前进与周期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>属性</th><th style="text-align:right;">缺省</th><th>说明</th></tr></thead><tbody><tr><td>Carousel</td><td><code>autoplay</code></td><td style="text-align:right;">4000ms</td><td>写 <code>true</code> 取缺省间隔，写数字即间隔；悬停与聚焦暂停，恢复后重新计满一个间隔；减弱动效下不自动起播</td></tr><tr><td>QuestionFlow</td><td><code>autoAdvanceDelay</code></td><td style="text-align:right;">480ms</td><td>单选题选定后自动到下一题前的等待；只前进到下一题，末题不替用户提交</td></tr><tr><td>Timer</td><td><code>interval</code></td><td style="text-align:right;">1000ms</td><td>显示刷新的周期，最小 16ms；到期由另一个精确计时器判定，不受它影响</td></tr><tr><td>LoadingBar</td><td><code>trickleSpeed</code></td><td style="text-align:right;">200ms</td><td>进度自动爬升的节拍；不大于 0 时不爬升</td></tr><tr><td>NumberField</td><td><code>changeDelay</code> / <code>changeInterval</code></td><td style="text-align:right;">300 / 50ms</td><td>按住步进按钮多久开始连发、连发的间隔</td></tr></tbody></table><h2 id="其他等待" tabindex="-1">其他等待 <a class="header-anchor" href="#其他等待" aria-label="Permalink to &quot;其他等待&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>属性</th><th style="text-align:right;">缺省</th><th>说明</th></tr></thead><tbody><tr><td>Scrollbar、ScrollArea</td><td><code>hideDelay</code></td><td style="text-align:right;">600ms</td><td>停止滚动与离开后多久隐藏；<code>Infinity</code> 不隐藏</td></tr><tr><td>Image</td><td><code>fallbackDelay</code></td><td style="text-align:right;">0</td><td>加载多久还没好才显示回退内容；<code>Infinity</code> 加载期间不显示</td></tr><tr><td>Approval</td><td><code>timeoutMs</code></td><td style="text-align:right;">无</td><td>不设就不计时；设了到点按超时处理</td></tr></tbody></table><p>首字母检索（Menu、Select、Listbox、Tree 等集合）在最后一次按键 350ms 后清空已输入的前缀，这是内部取值，不作为属性开放。</p><h2 id="与动效的分界" tabindex="-1">与动效的分界 <a class="header-anchor" href="#与动效的分界" aria-label="Permalink to &quot;与动效的分界&quot;">​</a></h2><ul><li>停留时长决定何时开始、何时结束，由组件属性给；变化本身的时长与曲线由<a href="/design/motion#令牌">动效令牌</a>给，组件不写固定毫秒。</li><li>NumberAnimation 的 <code>duration</code> 是补间时长，属于动效：减弱动效下直接落到终值。</li><li>Marquee 的 <code>speed</code> 是速率，不是停留。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/design/motion">动效</a> · <a href="/design/patterns">组件家族与模式</a></li></ul>',17)])])}const u=d(r,[["render",l]]);export{y as __pageData,u as default};
